 3→import (
 4→	"fmt"
 5→	"net/url"
 6→	"strings"
 7→)
 8→
 9→// PathBuilder constructs API paths with parameter substitution.
10→type PathBuilder struct {
11→	template string
12→	params   map[string]string
13→	query    url.Values
14→}
15→
16→// NewPath creates a new PathBuilder with the given template.
17→// Templates use {param} placeholders, e.g., "workspaces/{workspace_slug}/projects/{project_id}".
18→func NewPath(template string) *PathBuilder {
19→	return &PathBuilder{
20→		template: template,
21→		params:   make(map[string]string),
22→		query:    make(url.Values),
23→	}
24→}
25→
26→// Param sets a path parameter.
27→func (p *PathBuilder) Param(key, value string) *PathBuilder {
28→	p.params[key] = value
29→	return p
30→}
31→
32→// Workspace sets the workspace_slug parameter.
33→func (p *PathBuilder) Workspace(slug string) *PathBuilder {
34→	return p.Param("workspace_slug", slug)
35→}
36→
37→// Project sets the project_id parameter.
38→func (p *PathBuilder) Project(id string) *PathBuilder {
39→	return p.Param("project_id", id)
40→}
41→
42→// Query adds a query parameter.
43→func (p *PathBuilder) Query(key, value string) *PathBuilder {
44→	if value != "" {
45→		p.query.Set(key, value)
46→	}
47→	return p
48→}
49→
50→// QueryInt adds an integer query parameter.
51→func (p *PathBuilder) QueryInt(key string, value int) *PathBuilder {
52→	if value > 0 {
53→		p.query.Set(key, fmt.Sprintf("%d", value))
54→	}
55→	return p
56→}
57→
58→// Build constructs the final URL path with query string.
59→func (p *PathBuilder) Build() (string, error) {
60→	path := p.template
61→	for key, value := range p.params {
62→		placeholder := "{" + key + "}"
63→		if !strings.Contains(path, placeholder) {
64→			return "", fmt.Errorf("unknown path parameter: %s", key)
65→		}
66→		if value == "" {
67→			return "", fmt.Errorf("missing required path parameter: %s", key)
68→		}
69→		path = strings.ReplaceAll(path, placeholder, url.PathEscape(value))
70→	}
71→
72→	// Check for unresolved placeholders
73→	if idx := strings.Index(path, "{"); idx >= 0 {
74→		end := strings.Index(path[idx:], "}")
75→		if end > 0 {
76→			return "", fmt.Errorf("unresolved path parameter: %s", path[idx:idx+end+1])
77→		}
78→	}
79→
80→	if len(p.query) > 0 {
81→		path += "?" + p.query.Encode()
82→	}
83→
84→	return path, nil
85→}
