 7→// Formatter defines the interface for output formatting.
 8→type Formatter interface {
 9→	Format(data interface{}) error
10→}
11→
12→// Format outputs data using the specified format.
13→func Format(format string, data interface{}, columns []Column) error {
14→	switch format {
15→	case "table":
16→		return NewTableFormatter(columns).Format(data)
17→	default:
18→		return NewJSONFormatter().Format(data)
19→	}
20→}
21→
22→// FormatRaw outputs raw JSON data.
23→func FormatRaw(format string, data json.RawMessage, columns []Column) error {
24→	switch format {
25→	case "table":
26→		return NewTableFormatter(columns).Format(data)
27→	default:
28→		return NewJSONRawFormatter().Format(data)
29→	}
30→}
31→
32→// Column defines a table column.
33→type Column struct {
34→	Header string
35→	Field  string
