 8→// Quiet controls whether non-error output is suppressed.
 9→var Quiet bool
10→
11→// Print writes to stdout unless quiet mode is active.
12→func Print(format string, args ...interface{}) {
13→	if !Quiet {
14→		fmt.Fprintf(os.Stdout, format, args...)
15→	}
16→}
17→
18→// Println writes a line to stdout unless quiet mode is active.
19→func Println(args ...interface{}) {
20→	if !Quiet {
21→		fmt.Fprintln(os.Stdout, args...)
22→	}
23→}
24→
25→// Error writes to stderr (always shown, even in quiet mode).
26→func Error(format string, args ...interface{}) {
27→	fmt.Fprintf(os.Stderr, format, args...)
28→}
29→
30→// Errorln writes a line to stderr.
31→func Errorln(args ...interface{}) {
32→	fmt.Fprintln(os.Stderr, args...)
33→}
34→
35→// PrintID prints just an ID (useful for quiet mode after create/update).
36→func PrintID(id string) {
37→	fmt.Println(id)
38→}
