 8→)
 9→
10→// Factory provides shared dependencies for commands.
11→type Factory struct {
12→	Config    *config.Config
13→	client    *api.Client
14→	Format    string
15→	Workspace string
16→	Project   string
17→	Debug     bool
18→}
19→
20→// NewFactory creates a factory from config with CLI flag overrides.
21→func NewFactory(cfg *config.Config, workspace, project, format string, debug bool) *Factory {
22→	f := &Factory{
23→		Config:    cfg,
24→		Workspace: cfg.Workspace,
25→		Project:   cfg.Project,
26→		Format:    cfg.Format,
27→		Debug:     debug,
28→	}
29→
30→	// CLI flag overrides
31→	if workspace != "" {
32→		f.Workspace = workspace
33→	}
34→	if project != "" {
35→		f.Project = project
36→	}
37→	if format != "" {
38→		f.Format = format
39→	}
40→
41→	return f
42→}
43→
44→// Client returns the API client, creating it if needed.
45→func (f *Factory) Client() (*api.Client, error) {
46→	if f.client != nil {
47→		return f.client, nil
48→	}
49→
50→	if f.Config.BaseURL == "" {
51→		return nil, fmt.Errorf("base URL not configured.\n  Run `plane config init` to set up your Plane instance URL")
52→	}
53→	if f.Config.APIKey == "" {
54→		return nil, fmt.Errorf("API key not configured.\n  Run `plane config init` to set up your API key")
55→	}
56→
57→	f.client = api.NewClient(f.Config.BaseURL, f.Config.APIKey, api.WithDebug(f.Debug))
58→	return f.client, nil
59→}
60→
61→// RequireWorkspace returns the workspace slug or an error.
62→func (f *Factory) RequireWorkspace() (string, error) {
63→	if f.Workspace == "" {
64→		return "", fmt.Errorf("workspace not specified.\n  Use --workspace flag or set it with `plane config set workspace <slug>`")
65→	}
66→	return f.Workspace, nil
67→}
68→
69→// RequireProject returns the project ID or an error.
70→func (f *Factory) RequireProject() (string, error) {
71→	if f.Project == "" {
72→		return "", fmt.Errorf("project not specified.\n  Use --project flag or set it with `plane config set project <id>`")
73→	}
74→	return f.Project, nil
75→}
76→
77→// RequireWorkspaceAndProject returns both workspace and project or errors.
78→func (f *Factory) RequireWorkspaceAndProject() (string, string, error) {
79→	ws, err := f.RequireWorkspace()
80→	if err != nil {
81→		return "", "", err
82→	}
83→	proj, err := f.RequireProject()
84→	if err != nil {
85→		return "", "", err
86→	}
87→	return ws, proj, nil
88→}
